using System.Diagnostics;
using System.Text.Json;
using EmployeeOperations.Domain;
using EmployeeOperations.Infrastructure;
using Microsoft.EntityFrameworkCore;
var s = Settings.Parse(args); var options = new DbContextOptionsBuilder<EmployeeOperationsDbContext>().UseSqlServer(s.Connection).Options; await using var db = new EmployeeOperationsDbContext(options); await db.Database.MigrateAsync();
if (!await db.EquipmentRequests.AnyAsync()) { var random = new Random(s.Seed); for (var offset = 0; offset < s.Size; offset += 500) { for (var i = offset; i < Math.Min(offset + 500, s.Size); i++) { var r = EquipmentRequest.Create($"employee-{random.Next(1, 1001)}", $"Equipment-{random.Next(1, 101)}", $"Seeded request {i}", DateTimeOffset.UtcNow.AddMinutes(-i)); if (i % 3 != 0) r.Submit(r.EmployeeId, DateTimeOffset.UtcNow.AddSeconds(-i)); db.EquipmentRequests.Add(r); } await db.SaveChangesAsync(); db.ChangeTracker.Clear(); } }
async Task<long> Query() { var timer = Stopwatch.StartNew(); _ = await db.EquipmentRequests.GroupBy(x => x.Status).Select(g => new { g.Key, Count = g.Count() }).ToListAsync(); return timer.ElapsedMilliseconds; }
for (var i = 0; i < s.Warmups; i++) await Query(); var runs = new List<long>(); for (var i = 0; i < s.Runs; i++) runs.Add(await Query()); runs.Sort();
var output = new { s.Commit, Runtime = Environment.Version.ToString(), OS = Environment.OSVersion.ToString(), Architecture = System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture.ToString(), Environment.ProcessorCount, DatasetGenerator = "EmployeeOperations.Benchmarks/v1", s.Seed, DatasetSize = await db.EquipmentRequests.CountAsync(), Concurrency = 1, WarmupRuns = s.Warmups, MeasuredRuns = s.Runs, Baseline = new { RawMilliseconds = runs, MedianMilliseconds = runs[runs.Count / 2], P95Milliseconds = runs[(int)Math.Ceiling(runs.Count * .95) - 1] }, Optimization = "Not yet performed", OptimizedResult = (object?)null }; var json = JsonSerializer.Serialize(output, new JsonSerializerOptions { WriteIndented = true }); Console.WriteLine(json); if (s.Output is not null) await File.WriteAllTextAsync(s.Output, json);
file sealed record Settings(string Connection, string Commit, int Seed, int Size, int Warmups, int Runs, string? Output) { public static Settings Parse(string[] a) { string? Get(string n) { var i = Array.IndexOf(a, n); return i >= 0 && i + 1 < a.Length ? a[i + 1] : null; } return new(Get("--connection") ?? throw new ArgumentException("--connection is required"), Get("--commit") ?? throw new ArgumentException("--commit is required"), int.Parse(Get("--seed") ?? "1209"), int.Parse(Get("--size") ?? "10000"), int.Parse(Get("--warmups") ?? "2"), int.Parse(Get("--runs") ?? "10"), Get("--output")); } }
